// План specs/seo.md, 1.1 (кейс SEO-01). Гость, только GET-запрос к лендингу https://techory.ai (не к приложению). @prod-safe
import { test, expect } from '@playwright/test';

const SITEMAP = 'https://techory.ai/sitemap.xml';

test.describe('SEO — sitemap.xml (#f576f6d3)', () => {
  test('sitemap.xml returns 200 application/xml with a sitemaps.org urlset of public pages #f576f6d3 @desktop @prod-safe', async ({ request }) => {
    const res = await request.get(SITEMAP);
    expect(res.status()).toBe(200);
    expect(res.headers()['content-type']).toContain('application/xml');

    const body = await res.text();
    expect(body).toMatch(/^<\?xml version="1\.0"/);
    expect(body).toContain('<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">');
    expect(body).not.toContain('<div id="root"'); // не SPA-заглушка приложения

    const locs = [...body.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1].trim());
    expect(locs).toEqual(expect.arrayContaining(['https://techory.ai/', 'https://techory.ai/privacy', 'https://techory.ai/terms']));
    for (const loc of locs) expect(loc, 'loc — абсолютный адрес на techory.ai').toMatch(/^https:\/\/techory\.ai\//);
  });
});
